<template><section class="container section narrow"><p class="eyebrow">Личный кабинет</p><h1>Профиль</h1><div class="profile-card"><div class="avatar" aria-hidden="true">{{ initials }}</div><div><h2>{{ user?.name }}</h2><p class="meta">{{ user?.email }}</p><p v-if="user?.isDemo" class="notice">Демо-профиль предназначен только для проверки учебного проекта.</p></div></div><form class="profile-form" @submit.prevent="save"><div v-if="message" class="alert alert-success" role="status">{{ message }}</div><div v-if="error" class="alert alert-danger" role="alert">{{ error }}</div><label>Отображаемое имя<input v-model.trim="name" required minlength="2" maxlength="80" /></label><button class="btn btn-clay" :disabled="busy">{{ busy ? 'Сохраняем…' : 'Сохранить изменения' }}</button></form></section></template><script setup>import { computed, ref, watch } from 'vue'; import { useSession } from '../composables/useSession'; const {user,updateProfile}=useSession();const name=ref(user.value?.name||''),busy=ref(false),error=ref(''),message=ref('');watch(user,(value)=>{name.value=value?.name||''},{immediate:true});const initials=computed(()=>user.value?.name?.split(' ').map((x)=>x[0]).join('').slice(0,2).toUpperCase()||'TT');async function save(){busy.value=true;error.value='';message.value='';try{await updateProfile(name.value);message.value='Профиль обновлён.';}catch(e){error.value=e.message;}finally{busy.value=false;}}</script>
